mapper.select:
select
mn.* from Sec_Project mn
left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id left join Sec_Win_Notice wn on wn.Sec_Id=sec.Sec_Id where wn.Wn_Id=#{wnId}

select sec.Sec_Name as secName, sec.Sec_Bidding_Type as secBiddingType, mn.* from Sec_Win_Notice mn left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id where 1=1
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Wn_Create_Time DESC
limit #{params.start},#{params.size}

select sec.Sec_Name as secName, sec.Sec_Bidding_Type as secBiddingType, sec.Sec_Place as secPlace,
mn.* from Sec_Win_Notice mn left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id where 1=1
limit #{params.start},#{params.size}

select sec.Sec_Name as secName, case when pre.P_Name is null then sp.P_Name else pre.P_Name end as pName, case when pre.P_Category is null then sp.p_Category else pre.P_Category end as pCategory, case when pre.P_Build_Model is null then sp.P_Build_Model else pre.P_Build_Model end as pBuildModel, case when dpre.D_Name is null then sp.D_Name else dpre.D_Name end as pCompetentDepartmentName, mn.*, case when mn.P_Id is null then sp.P_Id else mn.P_Id end as pId from Sec_Win_Notice mn left join Sec_Info sec on sec.Sec_Id = mn.Sec_Id left join pre_project pre on pre.P_Id = mn.P_Id left join SYS_Department dpre on dpre.D_Id = pre.p_Competent_Department left join Sec_Bidding_Plan sbp on sbp.Bp_Id=sec.Bp_Id left join (select sp1.Sec_Id, sp1.P_ID, pro1.P_Name, pro1.p_Category, pro1.P_Build_Model, dpre1.D_Name from Sec_Project sp1 inner join pre_project pro1 on pro1.P_Id = sp1.P_Id left join SYS_Department dpre1 on dpre1.D_Id = pro1.p_Competent_Department where not exists (select 1 from Sec_Project sp2 inner join pre_project pro2 on pro2.P_Id = sp2.P_Id where sp2.Sec_Id = sp1.Sec_Id and pro2.P_Create_Time > pro1.P_Create_Time)) sp on sp.Sec_Id = mn.Sec_Id
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Wn_Create_Time desc

mapper.sql:
${authSql}

    and sbp.is_new = 1


    
        
            and (
            (case when pre.P_Name is null then sp.P_Name else pre.P_Name end) is null
            or
            (case when pre.P_Name is null then sp.P_Name else pre.P_Name end) = ''
            )
        
        
            and (case when pre.P_Name is null then sp.P_Name else pre.P_Name end) in
            
                #{pName}
            
        
    


    
        
            and (sec.sec_name is null or sec.sec_name = '')
        
        
            and sec.sec_name in
            
                #{secName}
            
        
    


    
        
            and (
            (case when pre.P_Category is null then sp.p_Category else pre.P_Category end) is null
            or
            (case when pre.P_Category is null then sp.p_Category else pre.P_Category end) = ''
            )
        
        
            and (case when pre.P_Category is null then sp.p_Category else pre.P_Category end) in
            
                #{pCategory}
            
        
    


    
        
            and (mn.Wn_Create_Uname is null or mn.Wn_Create_Uname = '')
        
        
            and mn.Wn_Create_Uname in
            
                #{createUname}
            
        
    


    
        
            and (mn.Wn_State is null or mn.Wn_State = '')
        
        
            and mn.Wn_State in
            
                #{state}
